"""The fixed crisis message, by country. Never generated by a model.

DRAFT: needs review by a qualified person for each country before launch there.
"""

from app.modules.regions import service

OPENING = (
    "I'm sorry you're going through this. I'm an AI mentor, and I can't give the kind of "
    "support this needs, but you deserve support right now.\n\n"
)
CLOSING = "\n\nIf I've misread what you said and you're okay, tell me and we can carry on."

# Used until the user has said which country they are in.
GENERIC = (
    "If you are in immediate danger, or you might act on thoughts of harming yourself or someone "
    "else, call your local emergency number now (999 in the UK and Ireland, 911 in the US and "
    "Canada, 112 in India).\n\n"
    "You can talk to someone for free: in the UK or Ireland, Samaritans are on 116 123. In the US "
    "or Canada, call or text 988. In India, Tele-MANAS is on 14416. Elsewhere, please contact your "
    "local emergency services or a crisis line in your country. Your doctor, or someone you "
    "trust, is a good next step too."
)


def crisis_message(country: str | None) -> str:
    region = service.get(country)
    if region is None:
        return OPENING + GENERIC + CLOSING
    body = (
        f"If you are in immediate danger, or you might act on thoughts of harming yourself or "
        f"someone else, {region.emergency} now.\n\n"
        "You can talk to someone, for free: " + " ".join(region.lines) + " " + region.other_help
    )
    return OPENING + body + CLOSING
